"""176 taktów Musikalisches Würfelspiel, K. 516f.

Wysokości z wydania Rellstaba (Berlin, ok. 1790), w C-dur.
Źródło jest w metrum 3/8. Wartości są podwojone, więc każdy takt
ma 3 ćwierćnuty i mieści się w menuecie 3/4.
None to pauza. Krotka liczb to jeden dźwięk albo akord.
Takty z dwoma zakończeniami mają tu tylko prima volta.
Powtórzenie gra to samo zakończenie.
"""

def events_from_measure(measure_id: int, shift: int = 0):
    """Prawa i lewa ręka jednego z 176 taktów, przesunięte o `shift` półtonów."""
    right, left = DICE_MEASURES[int(measure_id)]

    def convert(voice):
        events = []
        for pitches, duration in voice:
            if pitches is None:
                events.append({"type": "rest", "duration": float(duration)})
                continue
            sounded = [max(0, min(127, int(pitch) + int(shift))) for pitch in pitches]
            if len(sounded) == 1:
                events.append({
                    "type": "note",
                    "pitch": sounded[0],
                    "duration": float(duration),
                    "dynamic": "mf",
                })
            else:
                events.append({
                    "type": "chord",
                    "pitch": sounded,
                    "duration": float(duration),
                    "dynamic": "mf",
                })
        return events

    return convert(right), convert(left)


